export const getCreateSastRunUrl = () => {




  return `/api/qa/sast`
}

/**
 * @summary Create a SAST run by uploading source files
 */
export const createSastRun = async (sastRunInput: SastRunInput, options?: RequestInit): Promise<QaRun> => {
    const formData = new FormData();
formData.append(`projectName`, sastRunInput.projectName);
formData.append(`description`, sastRunInput.description);
if(sastRunInput.files !== undefined) {
 sastRunInput.files.forEach(value => formData.append(`files`, value));
 }

  return customFetch<QaRun>(getCreateSastRunUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





